1	export const CACHE_DEBOUNCE_DELAY = 500;
2	
3	const pendingSaves = new Map<string, ReturnType<typeof window.setTimeout>>();
4	const STRUCTURED_CACHE_ENTRY_KIND = "memos.editor-cache";
5	const STRUCTURED_CACHE_ENTRY_VERSION = 1;
6	
7	function deserializeContent(raw: string): string {
8	  try {
9	    const parsed = JSON.parse(raw) as { kind?: unknown; version?: unknown; content?: unknown };
10	    if (
11	      parsed.kind === STRUCTURED_CACHE_ENTRY_KIND &&
12	      parsed.version === STRUCTURED_CACHE_ENTRY_VERSION &&
13	      typeof parsed.content === "string"
14	    ) {
15	      return parsed.content;
16	    }
17	  } catch {
18	    // Drafts have historically been stored as raw markdown strings.
19	  }
20	
21	  return raw;
22	}
23	
24	function writeEntry(key: string, content: string): void {
25	  if (content.trim()) {
26	    localStorage.setItem(key, content);
27	  } else {
28	    localStorage.removeItem(key);
29	  }
30	}
31	
32	export const cacheService = {
33	  key: (username: string, cacheKey?: string): string => {
34	    return `${username}-${cacheKey || ""}`;
35	  },
36	
37	  save: (key: string, content: string) => {
38	    const pendingSave = pendingSaves.get(key);
39	    if (pendingSave) {
40	      window.clearTimeout(pendingSave);
41	    }
42	
43	    const timeoutId = window.setTimeout(() => {
44	      pendingSaves.delete(key);
45	
46	      writeEntry(key, content);
47	    }, CACHE_DEBOUNCE_DELAY);
48	
49	    pendingSaves.set(key, timeoutId);
50	  },
51	
52	  saveNow: (key: string, content: string) => {
53	    const pendingSave = pendingSaves.get(key);
54	    if (pendingSave) {
55	      window.clearTimeout(pendingSave);
56	      pendingSaves.delete(key);
57	    }
58	
59	    writeEntry(key, content);
60	  },
61	
62	  load(key: string): string {
63	    const raw = localStorage.getItem(key);
64	    return raw ? deserializeContent(raw) : "";
65	  },
66	
67	  clear(key: string): void {
68	    const pendingSave = pendingSaves.get(key);
69	    if (pendingSave) {
70	      window.clearTimeout(pendingSave);
71	      pendingSaves.delete(key);
72	    }
73	
74	    localStorage.removeItem(key);
75	  },
76	
77	  clearAll(): void {
78	    for (const timeoutId of pendingSaves.values()) {
79	      window.clearTimeout(timeoutId);
80	    }
81	    pendingSaves.clear();
82	  },
83	};
